using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var tools = new[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🌐 Searching: \"{query}\"");
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a query. Returns a list of result snippets."),
    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            notes.Add(title, content);
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note with a title and content for later summarization."),
    AIFunctionFactory.Create(
        () =>
        {
            var allNotes = notes.GetAll();
            return allNotes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", allNotes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "read_notes",
        "Reads all saved research notes."),
};

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your goal is to research a topic thoroughly and produce a summary.

        Workflow:
        1. Search the web for information on the given topic (perform 2-3 searches with different angles).
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, read your notes and produce a final comprehensive summary.

        Be thorough but concise. Focus on factual information from search results.
        """,
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = tools.Select(f => (AITool)f).ToList(),
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

Console.WriteLine("─────────────────────────────────────");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n─────────────────────────────────────");
Console.WriteLine($"\n📋 Notes collected: {notes.GetAll().Count}");
Console.WriteLine("✅ Research complete.");

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

/// <summary>Simulated web search tool that returns plausible results.</summary>
static class WebSearchTool
{
    public static Task<string> SearchAsync(string query)
    {
        // In production, replace with a real search API (Bing Search, Google Custom Search, etc.)
        var results = $"""
            Search results for: "{query}"

            1. [Wikipedia] {query} - Overview and key facts about the topic including historical context 
               and current developments. The topic has seen significant interest in recent years.

            2. [Research Paper] A comprehensive study on {query} published in 2025 highlights key trends, 
               challenges, and future directions in the field.

            3. [News Article] Recent developments in {query}: Experts predict continued growth and 
               innovation, with several breakthroughs expected in the near future.

            Note: This is a simulated search. Replace WebSearchTool.SearchAsync with a real search API 
            (e.g., Bing Web Search API) for production use.
            """;

        return Task.FromResult(results);
    }
}

